def check_s(S, k):
    # Condition 1: Every T in S has at least one successor in S.
    for T in S:
        has_successor = False
        for T_next in S:
            if T_next[:k-1] == T[1:]:
                has_successor = True
                break
        if not has_successor:
            return False

    # Condition 2: At least one T in S has at least two successors in S.
    has_two_successors = False
    for T in S:
        count = 0
        for T_next in S:
            if T_next[:k-1] == T[1:]:
                count += 1
        if count >= 2:
            has_two_successors = True
            break

    return has_two_successors

